d Taille (cm)"},{"name":"eyeColor","type":"STRING","required":false,"hint":"labeled Yeux"}],"rules":[{"level":"L3","code":"DOB_AFTER_ISSUE","expression":"dateOfBirth > dateOfIssue","severity":"ERROR"}]}'
